function setPath(root, path, value) {
  const parts = path.split(".");
  let cur = root;
  for (let i = 0; i < parts.length - 1; i++) {
    const key = parts[i];
    const nextIsIndex = /^\d+$/.test(parts[i + 1]);
    if (cur[key] == null) cur[key] = nextIsIndex ? [] : {};
    cur = cur[key];
  }
  cur[parts[parts.length - 1]] = value;
}

const langs = ["nl", "en", "ru", "uk"];
export const dict = { nl: {}, en: {}, ru: {}, uk: {} };

for (const row of rows) {
  if (row.length !== 5 || row.slice(1).some((cell) => !cell)) {
    throw new Error(`Incomplete translation: ${row[0]}`);
  }
  langs.forEach((lang, index) => setPath(dict[lang], row[0], row[index + 1]));
}

export function t(lang) {
  return dict[lang] || dict.ru;
}

export function translationGaps() {
  const base = paths(dict.nl);
  const gaps = [];
  for (const lang of ["en", "ru", "uk"]) {
    const have = new Set(paths(dict[lang]));
    for (const key of base) if (!have.has(key)) gaps.push(`${lang}:${key}`);
  }
  return gaps;
}

function paths(obj, prefix = "") {
  if (Array.isArray(obj)) return obj.flatMap((item, i) => paths(item, `${prefix}${i}.`));
  if (obj && typeof obj === "object") {
    return Object.entries(obj).flatMap(([k, v]) => paths(v, `${prefix}${k}.`));
  }
  return [prefix.slice(0, -1)];
}
